//! OpenCAD on the native engine (OVERHAUL_PLAN F2): a Tauri 2 window whose client area is
//! an `oc-render` wgpu swapchain with the React UI in a transparent webview on top (P2).
//!
//! - The webview runs the same UI as the browser and Electron builds. `src/native/*.ts`
//!   detect Tauri and route the kernel requests here (instead of the WebAssembly worker)
//!   and send the viewport's scene here (instead of drawing it with three.js).
//! - [`engine`]: documents regenerated by `oc-graph` on `oc-kernel-occt`, meshed by
//!   `oc-mesh`, on one engine thread.
//! - [`view`]: the render thread.
//! - [`smoke`]: `--smoke`, `--script=`, `--corpus` end-to-end checks.
//!
//! `cargo run -p oc-app` loads the Vite dev server (`npm run dev`); with
//! `--features custom-protocol` the built UI (`npm run build`) is embedded.
//!
//! Release builds are GUI-subsystem programs on Windows (no console window, F3); debug
//! builds keep their console for logs. `--smoke` output: [`smoke::emit`].
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]
mod asm;
mod bodymesh;
mod diag;
mod dialog;
mod engine;
mod pack;
mod pick;
mod process;
mod scene_dto;
mod smoke;
mod view;
mod webview_watch;

use engine::{Job, MeasureRef, MeshStore};
use oc_doc::{EdgeSig, FaceSig, Feature};
use scene_dto::{CameraDto, SceneDto};
use std::sync::mpsc::{channel, Sender};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;
use tauri::ipc::{InvokeBody, Request, Response};
use tauri::{Manager, State, WebviewUrl, WebviewWindow, WebviewWindowBuilder, WindowEvent};
use view::{Rect, ViewMsg};

struct AppState {
    jobs: Sender<Job>,
    view: Sender<ViewMsg>,
    smoke: Mutex<Option<Sender<String>>>,
    /// Where the webview's stuck-state dump goes (`smoke_dump`).
    dump: Mutex<Option<Sender<String>>>,
    smoke_args: smoke::Args,
    window: Mutex<Option<WebviewWindow>>,
    /// The document has unsaved changes (reported by the webview with [`app_doc`]).
    dirty: AtomicBool,
}

fn arcs(v: Vec<Feature>) -> Vec<Arc<Feature>> {
    v.into_iter().map(Arc::new).collect()
}

/// Sends a job to the engine and waits for its answer off the async runtime.
async fn ask<T: Send + 'static>(s: &AppState, make: impl FnOnce(Sender<Result<T, String>>) -> Job) -> Result<T, String> {
    let (tx, rx) = channel();
    let job = make(tx);
    let _call = diag::call(job.name());
    s.jobs.send(job).map_err(|_| "engine stopped".to_string())?;
    tauri::async_runtime::spawn_blocking(move || rx.recv().map_err(|_| "engine stopped".to_string()))
        .await
        .map_err(|e| e.to_string())?
        .and_then(|r| r)
}

#[tauri::command]
async fn engine_rebuild(s: State<'_, AppState>, features: Vec<Feature>, preview: Option<Feature>, quality: f64, config: Option<String>) -> Result<Response, String> {
    let (features, preview) = (arcs(features), preview.map(Arc::new));
    ask(&s, |reply| Job::Rebuild { features, preview, quality, config, reply }).await.map(Response::new)
}

#[tauri::command]
async fn engine_export(s: State<'_, AppState>, features: Vec<Feature>, format: String, quality: f64) -> Result<Response, String> {
    let features = arcs(features);
    ask(&s, |reply| Job::Export { features, format, quality, reply }).await.map(Response::new)
}

/// File > Export in the native app: written straight to the path the Save As dialog chose,
/// as SOLIDWORKS saves exports (G1a decision: native file access by path).
#[tauri::command]
async fn engine_export_to(s: State<'_, AppState>, features: Vec<Feature>, format: String, quality: f64, path: String) -> Result<u64, String> {
    let features = arcs(features);
    let bytes = ask(&s, |reply| Job::Export { features, format, quality, reply }).await?;
    std::fs::write(&path, &bytes).map_err(|e| format!("{path}: {e}"))?;
    Ok(bytes.len() as u64)
}

#[tauri::command]
async fn engine_mass_props(s: State<'_, AppState>, features: Vec<Feature>) -> Result<serde_json::Value, String> {
    let features = arcs(features);
    ask(&s, |reply| Job::MassProps { features, reply }).await
}

#[tauri::command]
async fn engine_measure(s: State<'_, AppState>, features: Vec<Feature>, refs: Vec<MeasureRef>) -> Result<serde_json::Value, String> {
    let features = arcs(features);
    ask(&s, |reply| Job::Measure { features, refs, reply }).await
}

#[tauri::command]
async fn engine_convert(
    s: State<'_, AppState>,
    features: Vec<Feature>,
    frame: engine::Frame,
    edges: Vec<EdgeSig>,
    faces: Vec<FaceSig>,
) -> Result<serde_json::Value, String> {
    let features = arcs(features);
    ask(&s, |reply| Job::Convert { features, frame, edges, faces, reply }).await
}

#[tauri::command]
async fn engine_clear_cache(s: State<'_, AppState>) -> Result<(), String> {
    s.jobs.send(Job::ClearCache).map_err(|_| "engine stopped".to_string())
}

// ---------------------------------------------------------------- assemblies (G1a)

#[tauri::command]
async fn asm_open(s: State<'_, AppState>, path: String) -> Result<serde_json::Value, String> {
    let path = std::path::PathBuf::from(path);
    ask(&s, |reply| Job::AsmOpen { path, reply }).await
}

#[tauri::command]
#[allow(clippy::too_many_arguments)]
async fn asm_build(s: State<'_, AppState>, doc: Box<oc_doc::AssemblyDocument>, path: Option<String>, lightweight: bool, quality: f64, overrides: Option<asm::Overrides>, probe: Option<bool>) -> Result<serde_json::Value, String> {
    let path = path.filter(|p| !p.is_empty()).map(std::path::PathBuf::from);
    let overrides = overrides.unwrap_or_default();
    // A probe (the SmartMates preview, G1d) leaves the last build as drags know it.
    let keep = !probe.unwrap_or(false);
    ask(&s, |reply| Job::AsmBuild { doc, path, lightweight, quality, overrides, keep, reply }).await
}

/// Move and Rotate Component by values (G1b).
#[tauri::command]
async fn asm_place(s: State<'_, AppState>, instance: String, to: oc_doc::Transform) -> Result<serde_json::Value, String> {
    ask(&s, |reply| Job::AsmPlace { instance, to, reply }).await
}

/// Mass properties of the open assembly's occurrences (G1b).
#[tauri::command]
async fn asm_mass(s: State<'_, AppState>, quality: f64) -> Result<serde_json::Value, String> {
    ask(&s, |reply| Job::AsmMass { quality, reply }).await
}

/// Interference Detection over the open assembly (G1c). `selected`: instance paths (none:
/// the whole assembly).
#[tauri::command]
#[allow(clippy::too_many_arguments)]
async fn asm_interference(s: State<'_, AppState>, selected: Vec<Vec<String>>, coincidence: bool, subassemblies: bool, include_hidden: bool, excluded: Option<Vec<Vec<String>>>, quality: f64) -> Result<serde_json::Value, String> {
    let paths = |v: Vec<Vec<String>>| v.into_iter().map(|p| p.iter().map(|x| oc_doc::Id::new(x)).collect()).collect();
    let opts = oc_asm::InterferenceOptions {
        selected: paths(selected),
        coincidence,
        subassemblies_as_components: subassemblies,
        include_hidden,
        excluded: paths(excluded.unwrap_or_default()),
    };
    ask(&s, |reply| Job::AsmInterference { opts, quality, reply }).await
}

/// Measure in the open assembly (G1c): picked entities of occurrences.
#[tauri::command]
async fn asm_measure(s: State<'_, AppState>, picks: Vec<asm::Pick>, quality: f64) -> Result<serde_json::Value, String> {
    ask(&s, |reply| Job::AsmMeasure { picks, quality, reply }).await
}

#[tauri::command]
async fn asm_drag(s: State<'_, AppState>, instance: String, grab: [f64; 3], target: [f64; 3], lever: f64) -> Result<serde_json::Value, String> {
    ask(&s, |reply| Job::AsmDrag { instance, grab, target, lever, reply }).await
}

#[tauri::command]
async fn asm_entity(s: State<'_, AppState>, part: String, kind: String, index: u32, quality: f64) -> Result<serde_json::Value, String> {
    ask(&s, |reply| Job::AsmEntity { part, kind, index, quality, reply }).await
}

/// An entity of an occurrence of the last build as it is now (G1d in-context references):
/// `{ entity, world }`, or an error when it is missing.
#[tauri::command]
async fn asm_ref(s: State<'_, AppState>, path: Vec<String>, entity: Box<oc_doc::MateEntity>, quality: f64) -> Result<serde_json::Value, String> {
    let path = path.iter().map(|x| oc_doc::Id::new(x)).collect();
    ask(&s, |reply| Job::AsmRef { path, entity, quality, reply }).await
}

#[tauri::command]
async fn asm_save(s: State<'_, AppState>, doc: Box<oc_doc::AssemblyDocument>, path: String, from: Option<String>, quality: f64, overrides: Option<asm::Overrides>) -> Result<serde_json::Value, String> {
    let path = std::path::PathBuf::from(path);
    let from = from.filter(|p| !p.is_empty()).map(std::path::PathBuf::from);
    let overrides = overrides.unwrap_or_default();
    ask(&s, |reply| Job::AsmSave { doc, path, from, quality, overrides, reply }).await
}

/// The native Open or Save As dialog; `kinds` are file types (`dialog::pick`).
#[tauri::command]
async fn app_pick_file(s: State<'_, AppState>, save: bool, kinds: Vec<String>, name: Option<String>) -> Result<Option<String>, String> {
    let owner = s.window.lock().expect("window").as_ref().and_then(hwnd).unwrap_or(0);
    tauri::async_runtime::spawn_blocking(move || dialog::pick(owner, save, &kinds, name.as_deref()))
        .await
        .map_err(|e| e.to_string())?
        .map(|p| p.map(|p| p.to_string_lossy().into_owned()))
}

#[cfg(windows)]
fn hwnd(w: &WebviewWindow) -> Option<isize> {
    w.hwnd().ok().map(|h| h.0 as isize)
}

#[cfg(not(windows))]
fn hwnd(_w: &WebviewWindow) -> Option<isize> {
    None
}

#[tauri::command]
async fn app_read_text(path: String) -> Result<String, String> {
    asm::read_text(std::path::Path::new(&path)).map(|v| v.as_str().unwrap_or_default().to_string())
}

#[tauri::command]
async fn app_write_text(path: String, text: String) -> Result<(), String> {
    asm::write_text(std::path::Path::new(&path), &text).map(|_| ())
}

#[tauri::command]
async fn view_frame(s: State<'_, AppState>, scene: Box<SceneDto>, camera: CameraDto, rect: Rect) -> Result<(), String> {
    s.view.send(ViewMsg::Frame { scene, camera, rect }).map_err(|_| "viewport stopped".to_string())
}

/// Waits off the async runtime for the render thread's answer.
async fn answer<T: Send + 'static>(s: &AppState, make: impl FnOnce(Sender<T>) -> ViewMsg) -> Result<T, String> {
    let (tx, rx) = channel();
    let msg = make(tx);
    let name = msg.name();
    let _call = diag::call(name);
    s.view.send(msg).map_err(|_| "viewport stopped".to_string())?;
    // A timeout says what the render thread was doing.
    tauri::async_runtime::spawn_blocking(move || rx.recv_timeout(Duration::from_secs(5)).map_err(|e| format!("viewport: no answer to {name} ({e}); render thread {}", diag::view_state())))
        .await
        .map_err(|e| e.to_string())?
}

/// What is under the pointer (F2b; `pick` in `src/native/view.ts`).
#[tauri::command]
async fn view_pick(s: State<'_, AppState>, req: Box<pick::PickReq>) -> Result<pick::PickReply, String> {
    answer(&s, |tx| ViewMsg::Pick(req, tx)).await
}

/// Model edges in a selection box.
#[tauri::command]
async fn view_box(s: State<'_, AppState>, req: Box<pick::BoxReq>) -> Result<pick::BoxReply, String> {
    answer(&s, |tx| ViewMsg::Box(req, tx)).await
}

/// What the last frame drew (G2b; native scripts): levels of detail of the part instances.
/// The first call turns the counting on and answers null.
#[tauri::command]
async fn view_stats(s: State<'_, AppState>) -> Result<Option<view::FrameStats>, String> {
    answer(&s, ViewMsg::Stats).await
}

/// A plane name rasterised by the webview: raw RGBA bytes, size and key in headers.
#[tauri::command]
async fn view_add_label(s: State<'_, AppState>, request: Request<'_>) -> Result<(), String> {
    let InvokeBody::Raw(rgba) = request.body() else { return Err("expected raw bytes".into()) };
    let h = |k: &str| request.headers().get(k).and_then(|v| v.to_str().ok()).and_then(|v| v.parse::<u32>().ok());
    let (Some(key), Some(width), Some(height)) = (h("x-key"), h("x-width"), h("x-height")) else {
        return Err("label headers missing".into());
    };
    if rgba.len() != (width * height * 4) as usize {
        return Err("label size mismatch".into());
    }
    s.view.send(ViewMsg::Label { key, rgba: rgba.clone(), width, height }).map_err(|_| "viewport stopped".to_string())
}

/// The process' memory and thread count (G3a; native scripts).
#[tauri::command]
fn app_process_stats() -> process::ProcessStats {
    process::stats()
}

#[tauri::command]
async fn app_info(s: State<'_, AppState>) -> Result<String, String> {
    answer(&s, ViewMsg::Info).await
}

/// The document's title and unsaved state (F3): the window title follows the document, as
/// in the Electron app, and closing a modified document asks first.
#[tauri::command]
async fn app_doc(s: State<'_, AppState>, title: String, dirty: bool) -> Result<(), String> {
    s.dirty.store(dirty, Ordering::Relaxed);
    let win = s.window.lock().expect("window").clone();
    if let Some(w) = win {
        w.set_title(&title).map_err(|e| e.to_string())?;
    }
    Ok(())
}

/// Close the window although the document has unsaved changes (the user said so).
#[tauri::command]
async fn app_close(s: State<'_, AppState>) -> Result<(), String> {
    s.dirty.store(false, Ordering::Relaxed);
    let win = s.window.lock().expect("window").clone();
    if let Some(w) = win {
        w.close().map_err(|e| e.to_string())?;
    }
    Ok(())
}

/// The webview's App exists (`window.opencad`): start the smoke script, if any.
#[tauri::command]
async fn app_ready(s: State<'_, AppState>) -> Result<(), String> {
    if !s.smoke_args.active() {
        return Ok(());
    }
    let js = smoke::script(&s.smoke_args).map_err(|e| e.to_string())?;
    let win = s.window.lock().expect("window").clone();
    diag::event(format!("app_ready (window {})", if win.is_some() { "known" } else { "not known yet" }));
    if let Some(w) = win {
        let r = w.eval(&js);
        diag::event(format!("script evaluated: {r:?}"));
        r.map_err(|e| e.to_string())?;
    }
    Ok(())
}

#[tauri::command]
async fn smoke_report(s: State<'_, AppState>, json: String) -> Result<(), String> {
    diag::event(format!("smoke_report ({} bytes)", json.len()));
    if let Some(tx) = s.smoke.lock().expect("smoke").take() {
        let _ = tx.send(json);
    }
    Ok(())
}

/// The webview's side of the stuck-state dump ([`smoke::DUMP`]).
#[tauri::command]
async fn smoke_dump(s: State<'_, AppState>, json: String) -> Result<(), String> {
    if let Some(tx) = s.dump.lock().expect("dump").take() {
        let _ = tx.send(json);
    }
    Ok(())
}

/// How long a check run waits for its script's report: `OC_SMOKE_TIMEOUT` seconds (loops
/// hunting a hang use less), else 600.
fn smoke_timeout() -> Duration {
    Duration::from_secs(std::env::var("OC_SMOKE_TIMEOUT").ok().and_then(|v| v.parse().ok()).unwrap_or(600))
}

/// What the app and the webview are doing when no report has come (`diag`, `smoke::DUMP`).
fn stuck_state(win: &WebviewWindow) -> serde_json::Value {
    let native = diag::dump();
    let (tx, rx) = channel();
    *win.app_handle().state::<AppState>().dump.lock().expect("dump") = Some(tx);
    let webview = match win.eval(smoke::DUMP) {
        Err(e) => serde_json::json!({ "evalError": e.to_string() }),
        Ok(()) => match rx.recv_timeout(Duration::from_secs(15)) {
            Ok(t) => serde_json::from_str(&t).unwrap_or(serde_json::Value::String(t)),
            Err(_) => serde_json::json!("no answer within 15 s"),
        },
    };
    serde_json::json!({ "native": native, "webview": webview, "nativeAfter": diag::dump()["pendingCalls"] })
}

/// Waits for the smoke report, saves the screenshots, prints `SMOKE {...}` and exits.
fn finish_smoke(win: WebviewWindow, args: smoke::Args, report: std::sync::mpsc::Receiver<String>, view: Sender<ViewMsg>) {
    let out = args.out.clone().unwrap_or_else(|| "smoke.png".into());
    let timeout = smoke_timeout();
    // No report in time: what the app was doing, and the screenshots as it was (exit code 2).
    let (mut report, timed_out) = match report.recv_timeout(timeout) {
        Ok(t) => (serde_json::from_str(&t).unwrap_or(serde_json::Value::Null), false),
        // A relaunched run (`webview_watch`) reports instead of this one.
        Err(_) if webview_watch::relaunched() => return,
        Err(_) => (serde_json::json!({ "exception": format!("no report within {} s", timeout.as_secs()), "stuck": stuck_state(&win) }), true),
    };
    // Let the last frame reach the screen.
    std::thread::sleep(Duration::from_millis(500));
    if let (Ok(pos), Ok(size)) = (win.inner_position(), win.inner_size()) {
        let px = smoke::grab(pos.x, pos.y, size.width as i32, size.height as i32);
        if !px.is_empty() {
            let _ = smoke::save_png(&out, &px, size.width, size.height);
        }
    }
    let (tx, rx) = channel();
    if view.send(ViewMsg::Capture(tx)).is_ok() {
        if let Ok(Some(img)) = rx.recv_timeout(Duration::from_secs(10)) {
            let stem = out.file_stem().unwrap_or_default().to_string_lossy().to_string();
            let _ = smoke::save_png(&out.with_file_name(format!("{stem}-viewport.png")), &img.data, img.width, img.height);
            report["viewport"] = serde_json::json!([img.width, img.height]);
        }
    }
    let mut code = if timed_out {
        2
    } else if report.get("exception").is_some() {
        1
    } else {
        0
    };
    if let (Some(dir), false) = (&args.corpus, timed_out) {
        let diffs = smoke::check_corpus(dir, &report);
        if !diffs.is_empty() {
            code = 1;
        }
        report["corpusDiffs"] = serde_json::json!(diffs);
    }
    report["app"] = serde_json::json!(env!("CARGO_PKG_VERSION"));
    report["occt"] = serde_json::json!(format!("{} {}", oc_kernel_occt::OCCT_VERSION, oc_kernel_occt::OCCT_LINKAGE));
    smoke::emit(&args, &format!("SMOKE {report}"));
    // A check run ends without asking about the document it modified.
    win.app_handle().state::<AppState>().dirty.store(false, Ordering::Relaxed);
    win.app_handle().exit(code);
}

fn main() {
    diag::now();
    // A geometry host (G3b): the engine starts this program again with this flag to
    // regenerate parts in a separate process; it never opens a window.
    if std::env::args().nth(1).as_deref() == Some(engine::GEOMETRY_HOST) {
        std::process::exit(oc_host::serve());
    }
    let args = smoke::Args::parse();
    if args.active() {
        smoke::attach_console();
    }
    let store = Arc::new(MeshStore::default());
    let jobs = engine::spawn(store.clone());
    let (view_tx, view_rx) = channel::<ViewMsg>();
    let (smoke_tx, smoke_rx) = channel::<String>();
    let state = AppState {
        jobs,
        view: view_tx.clone(),
        smoke: Mutex::new(args.active().then_some(smoke_tx)),
        dump: Mutex::new(None),
        smoke_args: args.clone(),
        window: Mutex::new(None),
        dirty: AtomicBool::new(false),
    };
    if args.active() {
        // A window that never reports must fail the run, not hang it.
        let a = args.clone();
        let t = smoke_timeout() + Duration::from_secs(300);
        std::thread::spawn(move || {
            std::thread::sleep(t);
            if webview_watch::relaunched() {
                return;
            }
            let r = serde_json::json!({ "exception": format!("watchdog: no report within {} s", t.as_secs()), "stuck": { "native": diag::dump() } });
            smoke::emit(&a, &format!("SMOKE {r}"));
            std::process::exit(3);
        });
    }
    let mut view_rx = Some(view_rx);
    let mut smoke_rx = Some(smoke_rx);
    tauri::Builder::default()
        .manage(state)
        .invoke_handler(tauri::generate_handler![
            engine_rebuild,
            engine_export,
            engine_export_to,
            engine_mass_props,
            engine_measure,
            engine_convert,
            engine_clear_cache,
            asm_open,
            asm_build,
            asm_ref,
            asm_drag,
            asm_place,
            asm_mass,
            asm_interference,
            asm_measure,
            asm_entity,
            asm_save,
            app_pick_file,
            app_read_text,
            app_write_text,
            view_frame,
            view_add_label,
            view_pick,
            view_box,
            view_stats,
            app_info,
            app_process_stats,
            app_doc,
            app_close,
            app_ready,
            smoke_report,
            smoke_dump
        ])
        .setup(move |app| {
            let mut builder = WebviewWindowBuilder::new(app, "main", WebviewUrl::App("index.html".into()));
            if args.active() {
                // Check runs use a WebView2 profile of their own, and start from the default
                // options (`smoke::early`): what the owner's app or an earlier run stored
                // (lod.js leaves Level of detail at 20) neither reaches nor comes from them.
                // The early script also keeps what the page did, for the stuck-state dump.
                if let Ok(dir) = app.path().app_local_data_dir() {
                    builder = builder.data_directory(dir.join("checks"));
                }
                builder = builder
                    .initialization_script(smoke::early(&format!("{}-{}", std::process::id(), diag::now())))
                    .on_page_load(|_, p| diag::event(format!("page {:?}: {}", p.event(), p.url())));
            }
            let win = builder
                .title("OpenCAD")
                .inner_size(1440.0, 900.0)
                .transparent(true)
                .always_on_top(args.active())
                .build()?;
            let st = app.state::<AppState>();
            *st.window.lock().expect("window") = Some(win.clone());
            diag::event("window built");
            webview_watch::watch(&win, args.active().then(|| args.clone()));
            let vt = view_tx.clone();
            let (handle, w2) = (app.handle().clone(), win.clone());
            win.on_window_event(move |e| match e {
                WindowEvent::Resized(size) => {
                    let _ = vt.send(ViewMsg::Resize(size.width, size.height));
                }
                // The webview's `beforeunload` guard does not run when the window is closed;
                // ask the webview instead (`__opencadConfirmClose` in src/ui/Shell.tsx), which
                // calls `app_close` if the user agrees. Unmodified documents close at once.
                WindowEvent::CloseRequested { api, .. } if handle.state::<AppState>().dirty.load(Ordering::Relaxed) => {
                    api.prevent_close();
                    let _ = w2.eval("window.__opencadConfirmClose ? window.__opencadConfirmClose() : window.__TAURI_INTERNALS__.invoke('app_close')");
                }
                _ => {}
            });
            let instance = wgpu::Instance::new(wgpu::InstanceDescriptor {
                backends: view::backends(),
                ..wgpu::InstanceDescriptor::new_without_display_handle()
            });
            let surface = instance.create_surface(win.clone())?;
            let size = win.inner_size()?;
            let rx = view_rx.take().expect("setup runs once");
            let store = store.clone();
            std::thread::Builder::new()
                .name("viewport".into())
                .spawn(move || view::run(instance, surface, (size.width, size.height), store, rx))?;
            if args.active() {
                let (w, a, r, v) = (win.clone(), args.clone(), smoke_rx.take().expect("setup runs once"), view_tx.clone());
                std::thread::spawn(move || finish_smoke(w, a, r, v));
            }
            Ok(())
        })
        .run(tauri::generate_context!())
        .expect("tauri");
}
